const fs   = require('fs');
const path = require('path');
const base = '/Users/jneal/n8n_projects';

const dirs = fs.readdirSync(base).filter(d => {
  try {
    const full = path.join(base, d);
    if (!fs.statSync(full).isDirectory()) return false;
    const hasVoiceover       = fs.existsSync(path.join(full, 'audio', 'voiceover_final.mp3'));
    const hasMetadataPackage = fs.existsSync(path.join(full, 'scripts', 'metadata_package.json'));
    return hasVoiceover && !hasMetadataPackage;
  } catch(e) { return false; }
}).sort();

if (dirs.length === 0)
  throw new Error('No Phase 2 ready projects. Need voiceover_final.mp3 but no metadata_package.json.');

const rows = dirs.map((d, i) => ({
  caseNumber: i + 1,
  slug: d,
  projectDir: path.join(base, d)
}));

return [{ json: { readyProjects: dirs, allRows: JSON.stringify(rows) } }];

