const fs   = require('fs');
const dur  = parseFloat(($input.first().json.stdout || '').trim()) || 0;
const mm   = Math.floor(dur / 60);
const ss   = Math.round(dur % 60);
const vars = (() => {
  try { return $('Load Project').first().json; } catch (_) {}
  return $('Load Project from Slug').first().json;
})();

const scriptText   = fs.readFileSync(vars.scriptPath, 'utf-8');
const voicePackage = JSON.parse(fs.readFileSync(vars.voicePackagePath, 'utf-8'));
const wordCount    = scriptText.split(/\s+/).filter(w => w.length > 0).length;
const wpm          = dur > 0 ? Math.round((wordCount / dur) * 60) : 150;

return [{ json: {
  ...vars,
  durationSeconds: Math.round(dur * 10) / 10,
  durationMMSS:    `${String(mm).padStart(2,'0')}:${String(ss).padStart(2,'0')}`,
  wordCount,
  wpm,
  scriptText,
  voicePackage
} }];

const fs   = require('fs');
const vars = $input.first().json;
const sys  = fs.readFileSync('/Users/jneal/n8n_projects/ruins_untold_system_prompts/media_segmentation.md', 'utf-8');

const fs2 = require('fs');
let slimTranscript = null;
if (vars.transcript) {
  try {
    const transcriptPath = vars.projectDir + '/scripts/transcript.json';
    const rawTranscript = JSON.parse(fs2.readFileSync(transcriptPath, 'utf-8'));
    const transcription = rawTranscript.transcription || [];
    const segments = transcription
      .filter(entry => entry.text && entry.text.trim().length > 0)
      .map(entry => ({
        text:  entry.text.trim(),
        start: (entry.offsets?.from ?? 0) / 1000,
        end:   (entry.offsets?.to   ?? 0) / 1000
      }));
    slimTranscript = {
      total_duration_seconds: vars.transcript.total_duration_seconds,
      segments
    };
  } catch (e) {
    // fallback to boundary words if transcript.json is unavailable
    slimTranscript = {
      total_duration_seconds: vars.transcript.total_duration_seconds,
      words: (vars.transcript.words || []).filter(w => /[.?!]$/.test(w.word))
    };
  }
}


const slimPackage = {
  topic:                           vars.voicePackage.topic,
  estimated_total_runtime_seconds: vars.voicePackage.estimated_total_runtime_seconds,
  segments: (vars.voicePackage.segments || []).map(s => ({
    segment_id:                 s.segment_id,
    act:                        s.act,
    sequence:                   s.sequence,
    word_count:                 s.word_count,
    estimated_duration_seconds: s.estimated_duration_seconds,
    narration_text:             s.narration_text
