function parseBridge(inp) {
  if (!inp.output || (inp.exitCode !== undefined && inp.exitCode !== 0)) {
    throw new Error('Music/SFX agent failed: ' + JSON.stringify(inp).substring(0, 400));
  }
  let raw = inp.output.trim();
  if (raw.startsWith('__disk__:')) raw = fs.readFileSync(raw.slice(9), 'utf-8').trim();
  const m = raw.match(/```(?:json)?\n?([\s\S]*?)```/);
  if (m) raw = m[1].trim();
  let out;
  try { out = JSON.parse(raw); } catch(e) {
    const s = raw.indexOf('{'), en = raw.lastIndexOf('}');
    if (s >= 0 && en >= 0) try { out = JSON.parse(raw.substring(s, en+1)); } catch(e2) {}
  }
  if (!out) throw new Error('Cannot parse music/sfx output. Raw: ' + raw.substring(0, 400));
  return out;
}

// Load visual result written by Step 5 code node
if (!fs.existsSync(vars.visualTmpPath)) {
  throw new Error('Visual assignment result not found: ' + vars.visualTmpPath);
}
const visualData   = JSON.parse(fs.readFileSync(vars.visualTmpPath, 'utf-8'));
const musicSfxData = parseBridge(inp);

const scenes    = visualData.scenes   || [];
const musicCues = musicSfxData.music_cues || [];
const sfxCues   = musicSfxData.sfx_cues   || [];
const sfxStats  = musicSfxData.stats       || {};
const totalDur  = vars.totalDuration;

const timeline = {
