    video_scenes:               scenes.filter(s => s.visual_type === 'video').length,
    pinned_scenes:              scenes.filter(s => s.visual_type === 'pinned_video').length,
    avg_scene_duration_seconds: parseFloat((totalDur / Math.max(scenes.length, 1)).toFixed(2)),
    music_cue_count:            musicCues.length,
    sfx_cue_count:              sfxCues.length,
    ambient_sfx_count:          sfxStats.ambient_sfx_count     || 0,
    punctuation_sfx_count:      sfxStats.punctuation_sfx_count || 0,
    transition_sfx_count:       sfxStats.transition_sfx_count  || 0,
    warnings:                   visualData.pinned_warning ? ['No pinned intro scene found'] : []
  }
};

fs.writeFileSync(vars.mediaTimelinePath, JSON.stringify(timeline, null, 2), 'utf-8');
console.log('Assembly complete: ' + scenes.length + ' scenes, ' + musicCues.length + ' music cues, ' + sfxCues.length + ' sfx cues');

return [{ json: returnVars }];

const fs   = require('fs');
const inp  = $input.first().json;
const vars = $('Build Image Chunk Prompt').first().json;
if (!inp.output || (inp.exitCode !== undefined && inp.exitCode !== 0))
  throw new Error('Image Agent failed (chunk ' + (vars.chunkIndex + 1) + '/' + vars.totalChunks + '): ' + (inp.error || JSON.stringify(inp)).substring(0, 300));
let raw = (inp.output || '').trim();
const m = raw.match(/```(?:json)?\n?([\s\S]*?)```/);
if (m) raw = m[1].trim();
let manifest;
try { manifest = JSON.parse(raw); }
catch(e) {
  const s = raw.indexOf('{'), en = raw.lastIndexOf('}');
