  manifest = JSON.parse(raw.substring(s, en + 1));
}
const prompts = manifest.image_prompts || [];
if (prompts.length < 1)
  throw new Error('Chunk ' + (vars.chunkIndex + 1) + ' returned 0 prompts. Output: ' + (inp.output || '').substring(0, 200));
fs.writeFileSync(vars.imageManifestChunkPath, JSON.stringify(manifest, null, 2), 'utf-8');
console.log('Chunk ' + (vars.chunkIndex + 1) + '/' + vars.totalChunks + ': ' + prompts.length + ' prompts saved');
return [{ json: { ...vars } }];

