if (missingIds.length > 0)
  throw new Error('Chunk ' + (vars.chunkIndex + 1) + '/' + vars.totalChunks +
    ' missing scene(s): ' + missingIds.join(', ') +
    ' — re-run this chunk before merging.');

fs.writeFileSync(vars.videoManifestChunkPath, JSON.stringify(manifest, null, 2), 'utf-8');
console.log('Video chunk ' + (vars.chunkIndex + 1) + '/' + vars.totalChunks +
  ': ' + prompts.length + ' prompts saved → ' + vars.videoManifestChunkPath);

return [{ json: { ...vars } }];

