// Run ffmpeg to read image dimensions (fastest available tool; outputs to stderr)
const r = spawnSync('/usr/local/bin/ffmpeg', ['-i', filepath], {
  encoding: 'utf8',
  timeout:  10000,
});

const output = (r.stderr || '') + (r.stdout || '');
// Parse first WIDTHxHEIGHT from Stream line
const m = output.match(/(\d{3,5})x(\d{3,5})/);
if (!m) return $input.all();  // Can't parse — pass through silently

const width  = parseInt(m[1], 10);
const height = parseInt(m[2], 10);
if (!width || !height) return $input.all();

const ratio    = width / height;
const expected = 16 / 9;
const tolerance = 0.05;

if (Math.abs(ratio - expected) > tolerance) {
  // Write mismatch record to scripts/dimension_mismatches.json
  const record = {
    filename,
    filepath,
    width,
    height,
    ratio:     Math.round(ratio    * 10000) / 10000,
    expected:  Math.round(expected * 10000) / 10000,
    detectedAt: new Date().toISOString(),
  };

  if (projectDir) {
    try { fs.mkdirSync(path.join(projectDir, 'scripts'), { recursive: true }); } catch {}
    const mismatchFile = path.join(projectDir, 'scripts', 'dimension_mismatches.json');
    let existing = [];
    try { existing = JSON.parse(fs.readFileSync(mismatchFile, 'utf-8')); } catch {}
    existing.push(record);
    fs.writeFileSync(mismatchFile, JSON.stringify(existing, null, 2), 'utf-8');
  }

  console.error(`DIMENSION MISMATCH: ${filename} is ${width}x${height} ` +
                `(ratio ${ratio.toFixed(4)}, expected 1.7778)`);
}

// Always continue the loop — never halt the batch for a dimension issue
return $input.all();

